INSERT INTO public.fact_claim (id, subject_table, subject_id, field_path, claim_text, source_id, citation, note, status)
SELECT id, subject_table, subject_id, field_path, claim_text, source_id, citation, note, status FROM jsonb_populate_recordset(NULL::public.fact_claim, '[{"subject_table": "event", "field_path": "description", "claim_text": "孙德昭安福门擒斩王仲先。", "citation": "卷262·天复元年（901）·zztj-v262-y0901-p001·原文件第40行", "note": "原文：春，正月，乙酉朔，王仲先入朝，至安福门，孙德昭擒斩之，；核对说明：主书明确孙斩王仲先；旧唐本纪正月甲申朔记昭宗反正，日次异，旧唐十二月另记孙等杀王；新五孙传作孙斩刘季述，不静改主书。", "status": "draft", "id": "32c5fe57-0063-5fbf-960e-1102ea5885e6", "subject_id": "17d8e992-611a-5e0e-8a13-a16f55257bda", "source_id": "98922abd-c843-5764-80e4-f5cd53a10632"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "901年春正月乙酉朔", "citation": "卷262·天复元年（901）·zztj-v262-y0901-p001·原文件第40行", "note": "原文：春，正月，乙酉朔，王仲先入朝，至安福门，孙德昭擒斩之，；核对说明：主书明确孙斩王仲先；旧唐本纪正月甲申朔记昭宗反正，日次异，旧唐十二月另记孙等杀王；新五孙传作孙斩刘季述，不静改主书。", "status": "draft", "id": "dbc6c12d-5600-55ae-9e25-462100d8a154", "subject_id": "17d8e992-611a-5e0e-8a13-a16f55257bda", "source_id": "98922abd-c843-5764-80e4-f5cd53a10632"}, {"subject_table": "person", "field_path": "description", "claim_text": "本段记孙德昭：擒斩王仲先者。", "citation": "卷262·天复元年（901）·zztj-v262-y0901-p001·原文件第40行", "note": "原文：春，正月，乙酉朔，王仲先入朝，至安福门，孙德昭擒斩之，驰诣少阳院，叩门呼曰：“逆贼已诛，请陛下出劳将士。”何后不信，曰：“果尔，以其首来！”德昭献其首，上乃与后毁扉而出。崔胤迎上御长乐门楼，帅百官称贺。周承诲擒刘季述、王彦范继至，方诘责，已为乱梃所毙。薛齐偓赴井死，出而斩之。灭四人之族，并诛其党二十馀人。宦官奉太子匿于左军，献传国宝。上曰：“裕幼弱，为凶竖所立，非其罪也。”命还东宫，黜为德王，复名裕。丙戌，以孙德昭同平章事，充静海节度使，赐姓名李继昭。；核对说明：只据本段确认参与身份；同名与异体字回查后复用。", "status": "draft", "id": "d78438cf-2ef9-5904-84bb-d3a26da3b90e", "subject_id": "15b4cbda-ba80-517c-be9b-b6a0da31fbf0", "source_id": "98922abd-c843-5764-80e4-f5cd53a10632"}, {"subject_table": "person_event", "field_path": "role", "claim_text": "孙德昭：擒斩王仲先者。", "citation": "卷262·天复元年（901）·zztj-v262-y0901-p001·原文件第40行", "note": "原文：春，正月，乙酉朔，王仲先入朝，至安福门，孙德昭擒斩之，；核对说明：参与身份依据本段措辞，不因同场出现推定额外关系。", "status": "draft", "id": "ae96135e-0ce9-517f-9063-5b98178111f5", "subject_id": "cba2c973-06ea-5a5d-98df-9ba076e46a34", "source_id": "98922abd-c843-5764-80e4-f5cd53a10632"}, {"subject_table":